public protocol FfiEngineProtocol: AnyObject, Sendable {
    
    func acknowledgeNewTopicSuggestion() 
    
    /**
     * Every day with recorded activity, sorted ascending by date —
     * Profile's heatmap renders these directly, oldest first.
     */
    func activityHistory()  -> [FfiDayActivity]
    
    /**
     * Every concept in the graph — Profile uses this to summarize
     * discovery/mastery across all of Explore in one pass.
     */
    func allConcepts()  -> [FfiConceptSummary]
    
    func applyArrayAction(sessionId: UInt64, action: FfiArrayAction) throws  -> FfiStepResult
    
    func applyCircuitAction(sessionId: UInt64, action: FfiCircuitAction) throws  -> FfiStepResult
    
    func applyGateAction(sessionId: UInt64, action: FfiGateAction) throws  -> FfiStepResult
    
    func applyPixelAction(sessionId: UInt64, action: FfiPixelAction) throws  -> FfiStepResult
    
    func arrayState(sessionId: UInt64) throws  -> FfiArrayState
    
    func bookmarkedConcepts()  -> [FfiConceptSummary]
    
    /**
     * The concepts a build's own `concept_ids` names, resolved to full
     * summaries — Build's session screen uses this to show "what this
     * project actually practices" and link straight back to Explore.
     * A dangling id (content typo, or a concept removed after the
     * build was authored) is silently skipped rather than surfaced as
     * an error, same policy as `bookmarked_concepts`.
     */
    func buildRelatedConcepts(buildId: String)  -> [FfiConceptSummary]
    
    func circuitState(sessionId: UInt64) throws  -> FfiCircuitState
    
    /**
     * Full concept detail as JSON — see the module doc comment for why
     * this one payload is JSON rather than a mirrored `uniffi::Record`.
     */
    func conceptDetailJson(conceptId: String)  -> String?
    
    func conceptsInDomain(domainId: String)  -> [FfiConceptSummary]
    
    /**
     * `None` only if the bundled content has zero practicable concepts
     * or `today` fails to parse — neither should happen in practice.
     */
    func dailyChallenge(today: String)  -> FfiDailyChallenge?
    
    /**
     * `None` means not yet attempted today.
     */
    func dailyChallengeResult(today: String)  -> Bool?
    
    func dailyStreak()  -> UInt32
    
    func discoveredConceptCount()  -> UInt32
    
    func domainChildren(domainId: String)  -> [FfiDomain]
    
    func endBuild(sessionId: UInt64) 
    
    /**
     * The puzzle pool right now: practicable concepts the player has
     * actually discovered. Empty until at least one discovered concept
     * has a working generator.
     */
    func gamePool()  -> [FfiConceptSummary]
    
    /**
     * The plain number shown at the top of the game screen — lifetime
     * correct answers in game mode.
     */
    func gameTotalCorrect()  -> UInt32
    
    func gateState(sessionId: UInt64) throws  -> FfiGateState
    
    func generateChallenge(conceptId: String, difficulty: UInt8, seed: UInt64)  -> FfiChallenge?
    
    /**
     * `id` is a caller-defined milestone id (e.g. "first_mastery",
     * "100_correct", "first_build") — see `BitEngine::has_celebrated`.
     */
    func hasCelebrated(id: String)  -> Bool
    
    func isBookmarked(conceptId: String)  -> Bool
    
    /**
     * Whether `concept_id` is due for review — see `BitEngine::is_rusty`.
     * Play reads this per pool candidate to weight puzzle selection
     * toward what's going stale instead of a flat random pick.
     */
    func isRusty(conceptId: String, today: String)  -> Bool
    
    func listBuilds()  -> [FfiBuildSummary]
    
    func longestDailyStreak()  -> UInt32
    
    func markCelebrated(id: String) 
    
    func mastery(conceptId: String)  -> FfiMastery
    
    /**
     * A concept that's genuinely ready to learn next (every prerequisite
     * already discovered), or `None` if nothing new is unlocked yet.
     */
    func nextLearnableConcept()  -> FfiConceptSummary?
    
    func noteFor(conceptId: String)  -> String?
    
    func objectiveStatus(sessionId: UInt64) throws  -> FfiObjectiveStatus
    
    func pixelState(sessionId: UInt64) throws  -> FfiPixelState
    
    /**
     * Every concept Play can actually offer a round for — see
     * `BitEngine::practicable_concepts`. Play picks from this list
     * rather than being hardcoded to one concept.
     */
    func practicableConcepts()  -> [FfiConceptSummary]
    
    func prerequisites(conceptId: String)  -> [FfiConceptSummary]
    
