enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case ContentLoad(path: String, message: String
    )
    case BuildStart(id: String, message: String
    )
    case SessionNotFound(id: UInt64
    )
    case WrongSessionKind(id: UInt64, expected: String, actual: String
    )
    case SaveParse(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .ContentLoad(
            path: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .BuildStart(
            id: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .SessionNotFound(
            id: try FfiConverterUInt64.read(from: &buf)
            )
        case 4: return .WrongSessionKind(
            id: try FfiConverterUInt64.read(from: &buf), 
            expected: try FfiConverterString.read(from: &buf), 
            actual: try FfiConverterString.read(from: &buf)
            )
        case 5: return .SaveParse(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .ContentLoad(path,message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .BuildStart(id,message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(id, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .SessionNotFound(id):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(id, into: &buf)
            
        
        case let .WrongSessionKind(id,expected,actual):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(id, into: &buf)
            FfiConverterString.write(expected, into: &buf)
            FfiConverterString.write(actual, into: &buf)
            
        
        case let .SaveParse(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


